import React, { useState } from "react";
import Swal from "sweetalert2";
import { Card, CardContent } from "../ui/card";
import { Badge } from "../ui/badge";
import { Button } from "../ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "../ui/dropdown-menu";
import {
  Calendar,
  Clock,
  Shield,
  CheckCircle,
  Users,
  Briefcase,
  MoreVertical,
  Edit,
  Trash2,
  Eye,
} from "lucide-react";
import { getStatusColor } from "../../utils/formatters";
import { formatDate, formatCurrency } from "../../utils/formatters";
import { projectService } from "../../services/projectService";
import { useAuth } from "../../contexts/AuthContext";

const getProjectTypeIcon = (type) => {
  const icons = {
    audit: Shield,
    certification: CheckCircle,
    consulting: Users,
    training: Briefcase,
  };
  const Icon = icons[type] || Shield;
  return <Icon className="w-4 h-4" />;
};

const getStatusLabel = (status) => {
  const labels = {
    planning: "Planeación",
    in_progress: "En Progreso",
    completed: "Completado",
    cancelled: "Cancelado",
  };
  return labels[status] || status;
};

export const ProjectCard = ({ project, onViewDetails, onUpdate }) => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(false);
  
  const isAdmin = ["super_admin", "admin"].includes(user?.role);
  const isClient = user?.role === 'client';
  const canEdit = isAdmin;
  const canDelete = isAdmin || project.created_by?._id === user?._id;

  const handleStatusChange = async (newStatus) => {
    if (!isAdmin) return;

    const result = await Swal.fire({
      title: '¿Cambiar estado?',
      html: `¿Deseas cambiar el estado a <strong>"${getStatusLabel(newStatus)}"</strong>?`,
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#16a34a',
      cancelButtonColor: '#6b7280',
      confirmButtonText: 'Sí, cambiar',
      cancelButtonText: 'Cancelar',
    });

    if (!result.isConfirmed) return;

    setLoading(true);
    try {
      await projectService.updateStatus(project._id, newStatus);
      
      Swal.fire({
        icon: 'success',
        title: '¡Estado Actualizado!',
        text: `El proyecto ahora está en estado: ${getStatusLabel(newStatus)}`,
        confirmButtonColor: '#16a34a',
        timer: 2000,
      });
      
      if (onUpdate) onUpdate();
    } catch (error) {
      console.error("Error updating status:", error);
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: error.response?.data?.detail || 'Error al actualizar estado',
        confirmButtonColor: '#dc2626',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    const result = await Swal.fire({
      title: '¿Eliminar Proyecto?',
      html: `
        <p>¿Estás seguro de eliminar el proyecto:</p>
        <p class="font-bold mt-2">"${project.project_name}"</p>
        <p class="text-sm text-red-600 mt-3">⚠️ Esta acción no se puede deshacer</p>
      `,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#dc2626',
      cancelButtonColor: '#6b7280',
      confirmButtonText: 'Sí, eliminar',
      cancelButtonText: 'Cancelar',
    });

    if (!result.isConfirmed) return;

    setLoading(true);
    try {
      await projectService.delete(project._id);
      
      Swal.fire({
        icon: 'success',
        title: '¡Eliminado!',
        text: 'El proyecto ha sido eliminado exitosamente',
        confirmButtonColor: '#16a34a',
        timer: 2000,
      });
      
      if (onUpdate) onUpdate();
    } catch (error) {
      console.error("Error deleting project:", error);
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: error.response?.data?.detail || 'Error al eliminar proyecto',
        confirmButtonColor: '#dc2626',
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card className={loading ? "opacity-50" : ""}>
      <CardContent className="p-4 sm:p-6">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
          <div className="flex items-start sm:items-center space-x-3 sm:space-x-4 flex-1 min-w-0">
            <div className="p-2 bg-green-100 rounded-lg flex-shrink-0">
              {getProjectTypeIcon(project.project_type)}
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="text-base sm:text-lg font-semibold text-gray-900 truncate">
                {project.project_name}
              </h3>
              <p className="text-xs sm:text-sm text-gray-600 line-clamp-2 mt-1">
                {project.description}
              </p>
              <div className="flex flex-wrap items-center gap-2 mt-2">
                <span className="text-xs text-gray-500 capitalize">
                  {project.project_type.replace("_", " ")}
                </span>
                {project.client_id && (
                  <>
                    <span className="text-gray-400">•</span>
                    <span className="text-xs text-gray-500 truncate max-w-[150px]">
                      {project.client_id.company_name}
                    </span>
                  </>
                )}
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2 sm:gap-3 w-full sm:w-auto">
            <div className="flex-1 sm:flex-initial">
              {/* Status Dropdown - Solo para admin */}
              {isAdmin ? (
                <DropdownMenu>
                  <DropdownMenuTrigger asChild disabled={loading}>
                    <button
                      className={`${getStatusColor(
                        project.status
                      )} px-3 py-1 rounded-full text-xs font-semibold cursor-pointer hover:opacity-80 transition-opacity w-full text-left`}
                    >
                      {getStatusLabel(project.status)} ▾
                    </button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end">
                    <DropdownMenuItem
                      onClick={() => handleStatusChange("planning")}
                      disabled={project.status === "planning"}
                    >
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-yellow-500"></div>
                        Planeación
                      </div>
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      onClick={() => handleStatusChange("in_progress")}
                      disabled={project.status === "in_progress"}
                    >
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                        En Progreso
                      </div>
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      onClick={() => handleStatusChange("completed")}
                      disabled={project.status === "completed"}
                    >
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-green-500"></div>
                        Completado
                      </div>
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      onClick={() => handleStatusChange("cancelled")}
                      disabled={project.status === "cancelled"}
                      className="text-red-600"
                    >
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-red-500"></div>
                        Cancelado
                      </div>
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              ) : (
                <Badge className={getStatusColor(project.status)}>
                  {getStatusLabel(project.status)}
                </Badge>
              )}

              <p className="text-base sm:text-lg font-bold text-gray-900 mt-2">
                {formatCurrency(project.budget)}
              </p>
            </div>

            {/* Menu de opciones - Solo para admin y creadores */}
            {(canEdit || canDelete) && !isClient && (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                    <MoreVertical className="h-4 w-4" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  {onViewDetails && (
                    <DropdownMenuItem onClick={() => onViewDetails(project)}>
                      <Eye className="w-4 h-4 mr-2" />
                      Ver Detalles
                    </DropdownMenuItem>
                  )}
                  {canEdit && (
                    <DropdownMenuItem onClick={() => onViewDetails?.(project)}>
                      <Edit className="w-4 h-4 mr-2" />
                      Editar
                    </DropdownMenuItem>
                  )}
                  {canDelete && (
                    <DropdownMenuItem
                      className="text-red-600"
                      onClick={handleDelete}
                    >
                      <Trash2 className="w-4 h-4 mr-2" />
                      Eliminar
                    </DropdownMenuItem>
                  )}
                </DropdownMenuContent>
              </DropdownMenu>
            )}
          </div>
        </div>

        <div className="mt-4 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 text-xs sm:text-sm text-gray-600">
          <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:space-x-4">
            <p className="flex items-center">
              <Calendar className="w-3 h-3 sm:w-4 sm:h-4 mr-2" />
              Inicio: {formatDate(project.start_date)}
            </p>
            <p className="flex items-center">
              <Clock className="w-3 h-3 sm:w-4 sm:h-4 mr-2" />
              {project.status === "completed" && project.actual_end_date
                ? `Finalizado: ${formatDate(project.actual_end_date)}`
                : `Estimado: ${formatDate(project.estimated_end_date)}`}
            </p>
          </div>
          {onViewDetails && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => onViewDetails(project)}
              className="w-full sm:w-auto"
            >
              Ver Detalles
            </Button>
          )}
        </div>
      </CardContent>
    </Card>
  );
};
